/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const {
        nlu_enabled
    } = api.state.nlu_settings;
    return (nlu_enabled) ? nlu_enabled.value : false;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const {
        auto_select_prompt_enabled_initial: va_topic_selected
    } = api.state.nlu_settings;
    return (va_topic_selected) ? va_topic_selected.value : false;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const {
        auto_select_prompt_enabled_mid: switched_topic_selected
    } = api.state.nlu_settings;
    return (switched_topic_selected) ? switched_topic_selected.value : false;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const nlu_settings_state = api.state.nlu_settings;
    const hideConfirmationMessage = (nlu_settings_state.auto_select_prompt_enabled_mid && !nlu_settings_state.auto_select_prompt_enabled_mid.value) && (nlu_settings_state.auto_select_prompt_enabled_initial && !nlu_settings_state.auto_select_prompt_enabled_initial.value);
    if (hideConfirmationMessage) {
        nlu_settings_state.auto_select_prompt_message = '';
    }

    return hideConfirmationMessage;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const {
        nlu_settings
    } = api.state;
    const {
        auto_select_prompt_message: confirmation_message
    } = nlu_settings;
    if (confirmation_message) {
        return confirmation_message.value;
    } else {
        nlu_settings.auto_select_prompt_message = {
            "value": "You'd like help with {Topic name}. Is that right?",
            "displayValue": "You'd like help with {Topic name}. Is that right?"
        };
        return nlu_settings.auto_select_prompt_message.value;
    }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const {
        nlu_settings
    } = api.state;
    const {
        nlu_enabled,
        nlu_driver
    } = nlu_settings;
    let invalid = false;
    if (nlu_enabled && nlu_enabled.value && nlu_driver && nlu_driver.value && nlu_driver.value == 'select') {
        invalid = true;
    }
    return invalid;

}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    var result = [{
        id: 'select',
        label: '--Please Select--'
    }];
    var nlu_service_provider = api.data.nlu_service_provider.results || [];
    nlu_service_provider.forEach(provider => {
        result.push({
            id: provider._row_data.uniqueValue,
            label: provider._row_data.displayValue
        });
    });
    return result;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const {
        nlu_driver
    } = api.state.nlu_settings;
    return (nlu_driver && nlu_driver.value) ? nlu_driver.value : 'select';
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function evaluateEvent({
    api,
    event
}) {
	const {
        table,
        sys_id
    } = event.payload;
    return {
        route: 'record',
        fields: {
            'table': table,
            'sysId': sys_id
        },
        params: {
            't': Date.now(),
            'aceNav':'virtual-agent'
        },
        redirect: null,
        passiveNavigation: null,
        title: null,
        multiInstField: null,
        targetRoute: null,
        external: null
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const {
        nlu_settings
    } = api.state;
    const {
        nlu_driver
    } = nlu_settings;
    let hideComponent = true;
    if (nlu_driver && nlu_driver.value && nlu_driver.value != 'select') {
        hideComponent = false;
    }
    return hideComponent;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api
}) {
    const {
        nlu_settings
    } = api.state;
    const {
        nlu_driver
    } = nlu_settings;
    const languageQueryParam = api.data.glideLanguages.output || '';
    let sysparm_fixed_query = '';
    if (nlu_driver && nlu_driver.value) {
        sysparm_fixed_query = sysparm_fixed_query + "language.driver=" + nlu_driver.value + languageQueryParam;
    }
    return sysparm_fixed_query;
}
